import pytest
from summarize import summarize


def test_summarize_basic():
    """Test basic summarization of revenue by region."""
    rows = [
        {'region': 'North', 'revenue': 100},
        {'region': 'South', 'revenue': 200},
        {'region': 'North', 'revenue': 50},
    ]
    result = summarize(rows)
    assert result == {'North': 150.0, 'South': 200.0}


def test_summarize_with_string_revenue():
    """Test that string revenue values are parsed correctly."""
    rows = [
        {'region': 'East', 'revenue': '150'},
        {'region': 'West', 'revenue': '250.5'},
    ]
    result = summarize(rows)
    assert result == {'East': 150.0, 'West': 250.5}


def test_summarize_ignores_missing_revenue():
    """Test that rows with missing revenue are ignored."""
    rows = [
        {'region': 'North', 'revenue': 100},
        {'region': 'South'},  # Missing revenue key
        {'region': 'East', 'revenue': 'invalid'},  # Unparseable revenue
        {'region': 'West', 'revenue': None},  # None revenue
    ]
    result = summarize(rows)
    assert result == {'North': 100.0}


def test_summarize_ignores_unparseable_revenue():
    """Test that rows with unparseable revenue are ignored."""
    rows = [
        {'region': 'A', 'revenue': 'not a number'},
        {'region': 'B', 'revenue': '$100'},  # Currency symbol not parseable by float()
        {'region': 'C', 'revenue': 300},
    ]
    result = summarize(rows)
    assert result == {'C': 300.0}


def test_summarize_empty_list():
    """Test with empty input."""
    result = summarize([])
    assert result == {}


def test_summarize_missing_region_key():
    """Test that rows missing region key are ignored."""
    rows = [
        {'region': 'North', 'revenue': 100},
        {'revenue': 200},  # Missing region key
    ]
    result = summarize(rows)
    assert result == {'North': 100.0}


def test_summarize_string_with_whitespace():
    """Test that revenue strings with whitespace are handled."""
    rows = [
        {'region': 'A', 'revenue': '  100  '},
        {'region': 'B', 'revenue': '\t200.5\n'},
    ]
    result = summarize(rows)
    assert result == {'A': 100.0, 'B': 200.5}


def test_summarize_mixed_types():
    """Test with mixed numeric types."""
    rows = [
        {'region': 'X', 'revenue': 100},  # int
        {'region': 'X', 'revenue': 50.5},  # float
        {'region': 'Y', 'revenue': '25'},  # string
    ]
    result = summarize(rows)
    assert result == {'X': 150.5, 'Y': 25.0}


def test_summarize_negative_revenue():
    """Test handling of negative revenue (refunds, etc.)."""
    rows = [
        {'region': 'A', 'revenue': 100},
        {'region': 'A', 'revenue': -20},
    ]
    result = summarize(rows)
    assert result == {'A': 80.0}

