"""
Tests for the summarize module.
"""

import pytest
from summarize import summarize


def test_basic_summarization():
    """Test basic revenue summarization by region."""
    rows = [
        {'region': 'North', 'revenue': 100},
        {'region': 'South', 'revenue': 200},
        {'region': 'North', 'revenue': 50}
    ]

    result = summarize(rows)

    assert result == {'North': 150.0, 'South': 200.0}


def test_string_revenue():
    """Test that string revenue values are parsed correctly."""
    rows = [
        {'region': 'East', 'revenue': '150'},
        {'region': 'West', 'revenue': '250.5'}
    ]

    result = summarize(rows)

    assert result == {'East': 150.0, 'West': 250.5}


def test_missing_revenue():
    """Test that rows with missing revenue are ignored."""
    rows = [
        {'region': 'North', 'revenue': 100},
        {'region': 'South'},  # Missing revenue
        {'region': 'East', 'revenue': 50}
    ]

    result = summarize(rows)

    assert result == {'North': 100.0, 'East': 50.0}


def test_missing_region():
    """Test that rows with missing region are ignored."""
    rows = [
        {'region': 'North', 'revenue': 100},
        {'revenue': 50},  # Missing region
        {'region': 'South', 'revenue': 200}
    ]

    result = summarize(rows)

    assert result == {'North': 100.0, 'South': 200.0}


def test_unparseable_revenue():
    """Test that rows with unparseable revenue are ignored."""
    rows = [
        {'region': 'North', 'revenue': 100},
        {'region': 'South', 'revenue': 'invalid'},  # Unparseable
        {'region': 'East', 'revenue': None},  # None revenue
        {'region': 'West', 'revenue': 200}
    ]

    result = summarize(rows)

    assert result == {'North': 100.0, 'West': 200.0}


def test_empty_rows():
    """Test handling of empty input."""
    result = summarize([])

    assert result == {}


def test_mixed_revenue_types():
    """Test with mixed numeric and string revenue types."""
    rows = [
        {'region': 'A', 'revenue': 100},
        {'region': 'A', 'revenue': '50'},
        {'region': 'A', 'revenue': '25.5'}
    ]

    result = summarize(rows)

    assert result == {'A': 175.5}


def test_float_result():
    """Test that results are floats."""
    rows = [
        {'region': 'North', 'revenue': 100},
        {'region': 'South', 'revenue': 200.5}
    ]

    result = summarize(rows)

    assert isinstance(result['North'], float)
    assert isinstance(result['South'], float)


def test_non_dict_rows():
    """Test that non-dict rows are ignored."""
    rows = [
        {'region': 'North', 'revenue': 100},
        'not a dict',  # Should be ignored
        None,  # Should be ignored
        {'region': 'South', 'revenue': 200}
    ]

    result = summarize(rows)

    assert result == {'North': 100.0, 'South': 200.0}


def test_negative_revenue():
    """Test handling of negative revenue values."""
    rows = [
        {'region': 'A', 'revenue': -50},
        {'region': 'A', 'revenue': 100}
    ]

    result = summarize(rows)

    assert result == {'A': 50.0}


if __name__ == '__main__':
    pytest.main([__file__, '-v'])

