def parse_kv(s):
    """Parse a string like 'key1=value1; key2=value2' into a dict.

    Semicolons separate pairs; the first '=' separates key from value;
    keys and values are whitespace-trimmed; a backslash-escaped semicolon \\;
    is a literal semicolon in a value.
    An empty string yields an empty dict.
    """
    if not s:
        return {}

    result = {}

    # We need to split by semicolons that are not escaped
    # First, let's parse the string manually to handle escaped semicolons

    pairs = []
    current_pair = ""
    i = 0
    while i < len(s):
        if s[i] == '\\' and i + 1 < len(s) and s[i + 1] == ';':
            # Escaped semicolon - add literal semicolon to current pair
            current_pair += ';'
            i += 2
        elif s[i] == ';':
            # Unescaped semicolon - this separates pairs
            pairs.append(current_pair)
            current_pair = ""
            i += 1
        else:
            current_pair += s[i]
            i += 1

    # Don't forget the last pair
    if current_pair or pairs:
        pairs.append(current_pair)

    # Now parse each pair into key and value
    for pair in pairs:
        pair = pair.strip()
        if not pair:
            continue

        # Find the first '=' to separate key from value
        eq_pos = pair.find('=')
        if eq_pos == -1:
            continue  # Skip malformed pairs without '='

        key = pair[:eq_pos].strip()
        value = pair[eq_pos + 1:].strip()

        result[key] = value

    return result

